/* Versioned route economy. All costs, fares and benefits are disclosed to the player. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.TryvoRouteEconomy=api;})(globalThis,()=>{
 const field=(key,label,min,max)=>({key,label,type:'number',min,max,value:0});
 function build(old,index){const size=index<4?5:index<8?7:9,mid=Math.floor(size/2),start=mid*size,end=start+size-1,at=start+mid,unit=1+Math.floor(index/4),cars=unit,capacity=cars*6,economy=index>=8,benefit=['passage','credit','toll'][index%3],toll=benefit==='toll'?2:0;
 const blocked=[];for(let row=1;row<size;row++)if(row!==mid)blocked.push(row*size+mid);
 const stops=economy?[{at:end-1,name:'Direct-platform riders',people:6,fare:2},{at:(mid-2)*size+size-3,name:'Upper-platform riders',people:5,fare:1},{at:(mid+2)*size+size-3,name:'Lower-platform riders',people:9,fare:1}]:[{at:end-1,name:old.stops[0].name,people:index<4?4:8,fare:0}];
 const repairs={[1]:unit+3,[size*size-2]:unit+4};
 const minDistance=size-1,baseCost=minDistance*unit,baseBudget=baseCost-(economy?12:0),maxDistance=minDistance+4;
 const gatePuzzle={title:['Repair the short crossing','Compare the two tracks','Negotiate the crossing toll'][index%3],person:'Ivo · route controller',kind:economy?'route-fares':'route-distance',skill:economy?'Net-cost reasoning':'Distance and cost',story:'This obstruction sits on the direct corridor. Solve the route calculation to restore the crossing.',rule:economy?`The direct trip is ${minDistance} km at ${unit} credits/km and carries 6 riders paying 2 each. A detour is ${minDistance+4} km and carries 9 riders paying 1 each. Compare fare minus travel cost; choose the better margin. Fare is settled at arrival.`:`The direct corridor is ${minDistance} km, at ${unit} travel tokens/km. The long detour is ${minDistance+4} km at the same rate. ${benefit==='toll'?'A separate 2-token toll will be waived when you solve this.':''} Calculate travel cost before tolls or bonuses.`,fields:economy?[field('direct','Direct margin: fares − travel cost',-100,100),field('detour','Detour margin: fares − travel cost',-100,100),{key:'choice',label:'Better margin',type:'select',options:['Direct trip','Detour trip']}]:[field('direct','Direct travel cost',0,100),field('saving','Travel tokens saved versus detour',0,100)],hint:economy?'Revenue is passengers × fare. Subtract distance × rate. A less negative margin is better.':'Multiply distance by the per-kilometre rate. Compare the two totals.',win:economy?'You compared revenue with distance cost, rather than choosing the largest crowd.':'You compared the actual travel costs and restored the shorter crossing.',note:'This is a fictional transport ledger. Points, travel tokens and fares are separate.'};
 return {...old,layoutVersion:3,cols:size,rows:size,start,end,budget:baseBudget,minDistance,maxDistance,unit,cars,capacity,economy,minimumRiders:economy?5:stops[0].people,stops,blocked,repairs,gate:null,switch:null,checkpoint:end,obstruction:{at,benefit,toll,puzzle:gatePuzzle},brief:economy?`Choose your passengers and reach the festival with net spending at most ${baseBudget} credits. Each kilometre costs ${unit}; fares settle at arrival. ${capacity} seats. Maximum ${maxDistance} km.`:`Unlock the direct crossing, collect your riders and reach the festival within ${baseBudget} travel tokens. Each kilometre costs ${unit}. ${capacity} seats.`,hint:'The crossing is on the direct corridor. Compare the live costs before adding a detour.',reply:'You made the route work by weighing distance, obstacles and the people on board.'};
 }
 function grade(l,a={}){const n=k=>Number(a[k]),p=l.obstruction.puzzle,e=l.economy,expected=e?12-l.minDistance*l.unit:l.minDistance*l.unit,second=e?9-(l.minDistance+4)*l.unit:4*l.unit;const valid=p.fields.every(f=>f.type==='number'?a[f.key]!==''&&a[f.key]!==undefined&&Number.isInteger(n(f.key))&&n(f.key)>=f.min&&n(f.key)<=f.max:f.options.includes(a[f.key]));const ok=valid&&n('direct')===expected&&n(e?'detour':'saving')===second&&(!e||a.choice==='Direct trip');return {ok,feedback:ok?p.win:e?`Direct: 12 − ${l.minDistance*l.unit} = ${expected}. Detour: 9 − ${(l.minDistance+4)*l.unit} = ${second}. Compare the two margins.`:`Direct costs ${l.minDistance} × ${l.unit} = ${expected}. The extra 4 km costs ${second} more. Check both figures.`};}
 function benefit(l){return l.obstruction.benefit==='credit'?'Unlock crossing + 1 travel credit':l.obstruction.benefit==='toll'?'Unlock crossing + waive the 2-token toll':'Unlock the direct crossing';}
 return {build,grade,benefit};
});
